-- Thirty playable questions, each with matching judge checkpoints in judge-data/question-tests.json.
insert into public.questions
  (id, title, difficulty, topic, description, encounter_pokemon_id, examples, starter_code, is_active)
values
  ('easy-arrays-contains-duplicate', 'Contains Duplicate', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Given an integer array nums, return true if any value appears at least twice. Otherwise return false.', 54, '[{"input": "nums = [1,2,3,1]", "output": "true"}, {"input": "nums = [1,2,3,4]", "output": "false"}]'::jsonb, '{"python": "def solve(nums):\n    return False\n", "javascript": "export function solve(nums) {\n  return false\n}\n"}'::jsonb, true),
  ('easy-arrays-best-profit', 'Best Time to Buy and Sell Stock', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Given daily prices, choose one day to buy and a later day to sell. Return the maximum profit, or 0 if no profit is possible.', 54, '[{"input": "prices = [7,1,5,3,6,4]", "output": "5"}, {"input": "prices = [7,6,4,3,1]", "output": "0"}]'::jsonb, '{"python": "def solve(prices):\n    return 0\n", "javascript": "export function solve(prices) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-arrays-move-zeroes', 'Move Zeroes', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Move every zero to the end of nums while preserving the relative order of nonzero values. Return the updated array.', 54, '[{"input": "nums = [0,1,0,3,12]", "output": "[1,3,12,0,0]"}, {"input": "nums = [0]", "output": "[0]"}]'::jsonb, '{"python": "def solve(nums):\n    return []\n", "javascript": "export function solve(nums) {\n  return []\n}\n"}'::jsonb, true),
  ('medium-arrays-rotate', 'Rotate Array', 'medium'::public.question_difficulty, 'arrays'::public.question_topic, 'Rotate nums to the right by k positions. Return the rotated array.', 54, '[{"input": "nums = [1,2,3,4,5,6,7], k = 3", "output": "[5,6,7,1,2,3,4]"}, {"input": "nums = [-1,-100,3,99], k = 2", "output": "[3,99,-1,-100]"}]'::jsonb, '{"python": "def solve(nums, k):\n    return []\n", "javascript": "export function solve(nums, k) {\n  return []\n}\n"}'::jsonb, true),
  ('easy-arrays-missing-number', 'Missing Number', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'nums contains distinct numbers from 0 through n with exactly one missing. Return the missing number.', 54, '[{"input": "nums = [3,0,1]", "output": "2"}, {"input": "nums = [0,1]", "output": "2"}]'::jsonb, '{"python": "def solve(nums):\n    return 0\n", "javascript": "export function solve(nums) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-arrays-intersection', 'Intersection of Two Arrays', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Return the distinct values present in both nums1 and nums2 in ascending order.', 54, '[{"input": "nums1 = [1,2,2,1], nums2 = [2,2]", "output": "[2]"}, {"input": "nums1 = [4,9,5], nums2 = [9,4,9,8,4]", "output": "[4,9]"}]'::jsonb, '{"python": "def solve(nums1, nums2):\n    return []\n", "javascript": "export function solve(nums1, nums2) {\n  return []\n}\n"}'::jsonb, true),
  ('easy-arrays-majority', 'Majority Element', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Return the value that appears more than floor(nums.length / 2) times. Such a value always exists.', 54, '[{"input": "nums = [3,2,3]", "output": "3"}, {"input": "nums = [2,2,1,1,1,2,2]", "output": "2"}]'::jsonb, '{"python": "def solve(nums):\n    return 0\n", "javascript": "export function solve(nums) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-arrays-sorted-squares', 'Squares of a Sorted Array', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'nums is sorted in nondecreasing order. Return the squares of its values in nondecreasing order.', 54, '[{"input": "nums = [-4,-1,0,3,10]", "output": "[0,1,9,16,100]"}, {"input": "nums = [-7,-3,2,3,11]", "output": "[4,9,9,49,121]"}]'::jsonb, '{"python": "def solve(nums):\n    return []\n", "javascript": "export function solve(nums) {\n  return []\n}\n"}'::jsonb, true),
  ('easy-arrays-binary-search', 'Binary Search', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Given distinct integers nums sorted in ascending order, return the index of target or -1 if it is absent.', 54, '[{"input": "nums = [-1,0,3,5,9,12], target = 9", "output": "4"}, {"input": "nums = [-1,0,3,5,9,12], target = 2", "output": "-1"}]'::jsonb, '{"python": "def solve(nums, target):\n    return -1\n", "javascript": "export function solve(nums, target) {\n  return -1\n}\n"}'::jsonb, true),
  ('easy-arrays-pivot-index', 'Find Pivot Index', 'easy'::public.question_difficulty, 'arrays'::public.question_topic, 'Return the first index whose left-side sum equals its right-side sum. An empty side has sum 0. Return -1 if none exists.', 54, '[{"input": "nums = [1,7,3,6,5,6]", "output": "3"}, {"input": "nums = [1,2,3]", "output": "-1"}]'::jsonb, '{"python": "def solve(nums):\n    return -1\n", "javascript": "export function solve(nums) {\n  return -1\n}\n"}'::jsonb, true),
  ('easy-strings-reverse-words', 'Reverse Words in a String', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Reverse the order of words in s. A word is a run of non-space characters. Join words with one space.', 25, '[{"input": "s = \"the sky is blue\"", "output": "\"blue is sky the\""}, {"input": "s = \"  hello world  \"", "output": "\"world hello\""}]'::jsonb, '{"python": "def solve(s):\n    return \"\"\n", "javascript": "export function solve(s) {\n  return \"\"\n}\n"}'::jsonb, true),
  ('easy-strings-valid-anagram', 'Valid Anagram', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Return true if t contains the same characters with the same counts as s, in any order.', 25, '[{"input": "s = \"anagram\", t = \"nagaram\"", "output": "true"}, {"input": "s = \"rat\", t = \"car\"", "output": "false"}]'::jsonb, '{"python": "def solve(s, t):\n    return False\n", "javascript": "export function solve(s, t) {\n  return false\n}\n"}'::jsonb, true),
  ('easy-strings-common-prefix', 'Longest Common Prefix', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Return the longest prefix shared by every string in strs. If there is no shared prefix, return an empty string.', 25, '[{"input": "strs = [\"flower\",\"flow\",\"flight\"]", "output": "\"fl\""}, {"input": "strs = [\"dog\",\"racecar\",\"car\"]", "output": "\"\""}]'::jsonb, '{"python": "def solve(strs):\n    return \"\"\n", "javascript": "export function solve(strs) {\n  return \"\"\n}\n"}'::jsonb, true),
  ('easy-strings-roman-integer', 'Roman to Integer', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Convert a valid Roman numeral s to its integer value. Subtractive pairs such as IV and IX are allowed.', 25, '[{"input": "s = \"III\"", "output": "3"}, {"input": "s = \"MCMXCIV\"", "output": "1994"}]'::jsonb, '{"python": "def solve(s):\n    return 0\n", "javascript": "export function solve(s) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-strings-valid-parentheses', 'Valid Parentheses', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Return true if every opening bracket has a matching closing bracket in the correct order.', 25, '[{"input": "s = \"()[]{}\"", "output": "true"}, {"input": "s = \"(]\"", "output": "false"}]'::jsonb, '{"python": "def solve(s):\n    return False\n", "javascript": "export function solve(s) {\n  return false\n}\n"}'::jsonb, true),
  ('medium-strings-longest-substring', 'Longest Substring Without Repeating Characters', 'medium'::public.question_difficulty, 'strings'::public.question_topic, 'Return the length of the longest contiguous substring of s with no repeated character.', 25, '[{"input": "s = \"abcabcbb\"", "output": "3"}, {"input": "s = \"bbbbb\"", "output": "1"}]'::jsonb, '{"python": "def solve(s):\n    return 0\n", "javascript": "export function solve(s) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-strings-isomorphic', 'Isomorphic Strings', 'easy'::public.question_difficulty, 'strings'::public.question_topic, 'Return true if each character of s can be mapped consistently to one unique character of t.', 25, '[{"input": "s = \"egg\", t = \"add\"", "output": "true"}, {"input": "s = \"foo\", t = \"bar\"", "output": "false"}]'::jsonb, '{"python": "def solve(s, t):\n    return False\n", "javascript": "export function solve(s, t) {\n  return false\n}\n"}'::jsonb, true),
  ('medium-math-count-primes', 'Count Primes', 'medium'::public.question_difficulty, 'math'::public.question_topic, 'Return the number of prime numbers strictly less than n.', 74, '[{"input": "n = 10", "output": "4"}, {"input": "n = 0", "output": "0"}]'::jsonb, '{"python": "def solve(n):\n    return 0\n", "javascript": "export function solve(n) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-math-palindrome-number', 'Palindrome Number', 'easy'::public.question_difficulty, 'math'::public.question_topic, 'Return true if the decimal digits of x read the same from both ends. Negative values are not palindromes.', 74, '[{"input": "x = 121", "output": "true"}, {"input": "x = -121", "output": "false"}]'::jsonb, '{"python": "def solve(x):\n    return False\n", "javascript": "export function solve(x) {\n  return false\n}\n"}'::jsonb, true),
  ('easy-math-power-two', 'Power of Two', 'easy'::public.question_difficulty, 'math'::public.question_topic, 'Return true if n is a positive power of two.', 74, '[{"input": "n = 1", "output": "true"}, {"input": "n = 16", "output": "true"}]'::jsonb, '{"python": "def solve(n):\n    return False\n", "javascript": "export function solve(n) {\n  return false\n}\n"}'::jsonb, true),
  ('medium-math-trailing-zeroes', 'Factorial Trailing Zeroes', 'medium'::public.question_difficulty, 'math'::public.question_topic, 'Return the number of trailing zero digits in n factorial.', 74, '[{"input": "n = 3", "output": "0"}, {"input": "n = 5", "output": "1"}]'::jsonb, '{"python": "def solve(n):\n    return 0\n", "javascript": "export function solve(n) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-dp-house-robber', 'House Robber', 'medium'::public.question_difficulty, 'dp'::public.question_topic, 'Choose nonadjacent houses to maximize the sum of their values. Return the largest possible sum.', 65, '[{"input": "nums = [1,2,3,1]", "output": "4"}, {"input": "nums = [2,7,9,3,1]", "output": "12"}]'::jsonb, '{"python": "def solve(nums):\n    return 0\n", "javascript": "export function solve(nums) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-dp-min-cost-stairs', 'Min Cost Climbing Stairs', 'easy'::public.question_difficulty, 'dp'::public.question_topic, 'Pay cost[i] when stepping on stair i. You may start at stair 0 or 1 and climb one or two steps. Return the minimum cost to step beyond the array.', 65, '[{"input": "cost = [10,15,20]", "output": "15"}, {"input": "cost = [1,100,1,1,1,100,1,1,100,1]", "output": "6"}]'::jsonb, '{"python": "def solve(cost):\n    return 0\n", "javascript": "export function solve(cost) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-dp-unique-paths', 'Unique Paths', 'medium'::public.question_difficulty, 'dp'::public.question_topic, 'A robot starts at the top-left of an m by n grid and moves only right or down. Return the number of ways to reach the bottom-right.', 65, '[{"input": "m = 3, n = 7", "output": "28"}, {"input": "m = 3, n = 2", "output": "3"}]'::jsonb, '{"python": "def solve(m, n):\n    return 0\n", "javascript": "export function solve(m, n) {\n  return 0\n}\n"}'::jsonb, true),
  ('medium-dp-coin-change', 'Coin Change', 'medium'::public.question_difficulty, 'dp'::public.question_topic, 'Given coin denominations and an amount, return the fewest coins needed to make the amount, or -1 if impossible. Coins may be reused.', 65, '[{"input": "coins = [1,2,5], amount = 11", "output": "3"}, {"input": "coins = [2], amount = 3", "output": "-1"}]'::jsonb, '{"python": "def solve(coins, amount):\n    return -1\n", "javascript": "export function solve(coins, amount) {\n  return -1\n}\n"}'::jsonb, true),
  ('medium-graphs-flood-fill', 'Flood Fill', 'medium'::public.question_difficulty, 'graphs'::public.question_topic, 'Starting at image[sr][sc], change that cell and every connected cell with its original color to color. Cells connect horizontally or vertically. Return the new image.', 92, '[{"input": "image = [[1,1,1],[1,1,0],[1,0,1]], sr = 1, sc = 1, color = 2", "output": "[[2,2,2],[2,2,0],[2,0,1]]"}, {"input": "image = [[0,0,0],[0,0,0]], sr = 0, sc = 0, color = 0", "output": "[[0,0,0],[0,0,0]]"}]'::jsonb, '{"python": "def solve(image, sr, sc, color):\n    return []\n", "javascript": "export function solve(image, sr, sc, color) {\n  return []\n}\n"}'::jsonb, true),
  ('medium-graphs-components', 'Number of Connected Components', 'medium'::public.question_difficulty, 'graphs'::public.question_topic, 'Given n nodes numbered 0 through n-1 and undirected edges, return the number of connected components.', 92, '[{"input": "n = 5, edges = [[0,1],[1,2],[3,4]]", "output": "2"}, {"input": "n = 5, edges = [[0,1],[1,2],[2,3],[3,4]]", "output": "1"}]'::jsonb, '{"python": "def solve(n, edges):\n    return 0\n", "javascript": "export function solve(n, edges) {\n  return 0\n}\n"}'::jsonb, true),
  ('easy-graphs-valid-path', 'Find if Path Exists in Graph', 'easy'::public.question_difficulty, 'graphs'::public.question_topic, 'Given an undirected graph, return true if there is a path from source to destination.', 92, '[{"input": "n = 3, edges = [[0,1],[1,2],[2,0]], source = 0, destination = 2", "output": "true"}, {"input": "n = 6, edges = [[0,1],[0,2],[3,5],[5,4],[4,3]], source = 0, destination = 5", "output": "false"}]'::jsonb, '{"python": "def solve(n, edges, source, destination):\n    return False\n", "javascript": "export function solve(n, edges, source, destination) {\n  return false\n}\n"}'::jsonb, true),
  ('easy-trees-same-tree', 'Same Tree', 'easy'::public.question_difficulty, 'trees'::public.question_topic, 'Two binary trees are given as level-order arrays with null gaps. Return true if their structure and values match.', 133, '[{"input": "p = [1,2,3], q = [1,2,3]", "output": "true"}, {"input": "p = [1,2], q = [1,null,2]", "output": "false"}]'::jsonb, '{"python": "def solve(p, q):\n    return False\n", "javascript": "export function solve(p, q) {\n  return false\n}\n"}'::jsonb, true),
  ('easy-trees-min-depth', 'Minimum Depth of Binary Tree', 'easy'::public.question_difficulty, 'trees'::public.question_topic, 'The tree is a level-order array with null gaps. Return the number of nodes on the shortest root-to-leaf path; return 0 for an empty tree.', 133, '[{"input": "root = [3,9,20,null,null,15,7]", "output": "2"}, {"input": "root = [2,null,3,null,null,null,4]", "output": "3"}]'::jsonb, '{"python": "def solve(root):\n    return 0\n", "javascript": "export function solve(root) {\n  return 0\n}\n"}'::jsonb, true)
on conflict (id) do update set
  title = excluded.title,
  difficulty = excluded.difficulty,
  topic = excluded.topic,
  description = excluded.description,
  encounter_pokemon_id = excluded.encounter_pokemon_id,
  examples = excluded.examples,
  starter_code = excluded.starter_code,
  is_active = excluded.is_active;

-- Keep the earlier twenty problem statements as complete as the new catalog.
update public.questions as question
set description = catalog.description
from (values
  ('easy-arrays-two-sum', 'Given an array of integers nums and an integer target, find two distinct indices whose values add to target. Return their indices in ascending order. Exactly one answer exists.'),
  ('easy-strings-palindrome', 'Given a string s, keep only its alphanumeric characters and compare them without regard to case. Return true if the resulting string reads the same forward and backward.'),
  ('easy-math-fizz-buzz-count', 'Given a positive integer n, count the integers from 1 through n that are divisible by 3 or by 5. Count a number divisible by both only once.'),
  ('medium-arrays-longest-streak', 'Given an array nums of daily score changes, choose one nonempty contiguous subarray. Return the largest sum that any such streak can produce.'),
  ('medium-strings-group-anagrams', 'Given an array of lowercase words, words belong to the same group when they contain the same characters with the same counts. Return the number of distinct anagram groups.'),
  ('medium-trees-level-sum', 'A binary tree is represented by level-order values with null entries for missing nodes. Return the one-based level whose node values have the largest sum.'),
  ('medium-graphs-island-count', 'Given a grid of 0s and 1s, count groups of connected land cells. Land cells connect only to horizontal or vertical neighbors.'),
  ('hard-dp-coin-routes', 'Given coin denominations and a target, return how many combinations make the target exactly. You may use each denomination repeatedly; changing the order does not make a new combination.'),
  ('hard-graphs-shortest-signal', 'There are n nodes labeled from 1 to n. Each directed edge contains a source, destination, and positive travel time. A signal starts at start; return the time when every node has received it, or -1 if a node cannot be reached.'),
  ('hard-math-prime-window', 'Given a maximum value n and inclusive range queries [left, right], return the number of prime integers in each range in query order.'),
  ('easy-arrays-merge-tracks', 'Given two arrays a and b sorted in nondecreasing order, return one sorted array containing every value from both inputs, including duplicates.'),
  ('easy-strings-first-unique', 'Given a string s, return the zero-based index of its first character that occurs exactly once. Return -1 when no character is unique.'),
  ('easy-trees-max-depth', 'A binary tree is represented by level-order values with null entries for missing nodes. Return the number of nodes along the longest root-to-leaf path; return 0 for an empty tree.'),
  ('medium-arrays-product-signal', 'Given an integer array nums, return an array answer where answer[i] is the product of every value in nums except nums[i]. Preserve the original element order.'),
  ('medium-graphs-course-order', 'There are n courses numbered from 0 to n-1. Each prerequisite pair [course, required] means required must be finished first. Return true if every course can be finished.'),
  ('medium-dp-climb-routes', 'You are climbing n steps and may take either one or two steps at a time. Return the number of distinct sequences of moves that reach the top.'),
  ('medium-math-subarray-divisible', 'Given an integer array nums and a positive integer k, count the nonempty contiguous subarrays whose sum is divisible by k.'),
  ('hard-trees-path-sum', 'A binary tree is represented by level-order values with null entries for missing nodes. A path follows parent-child edges without repeating a node and may start and end anywhere. Return the largest path sum.'),
  ('hard-dp-edit-distance', 'Given strings word1 and word2, return the fewest single-character insertions, deletions, or replacements required to turn word1 into word2.'),
  ('hard-strings-min-window', 'Given strings s and t, return the shortest contiguous substring of s containing every character of t with at least its required count. Return an empty string if no such window exists.')
) as catalog(id, description)
where question.id = catalog.id;
